using System;using UnityEngine;namespace Exoduser.UnityPort {internal static class NativeSkillIconPainter {internal static Texture2D Circle(Texture2D source,bool dim){if(source==null)return null;if(!source.isReadable)throw new InvalidOperationException("Source skill icon must be readable: "+source.name);const int size=256;var result=new Texture2D(size,size,TextureFormat.RGBA32,false){name=source.name+(dim?" circle dim":" circle"),wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Bilinear};var pixels=new Color[size*size];float crop=1/1.18f,cropX=crop*Mathf.Min(1,source.height/(float)source.width),cropY=crop*Mathf.Min(1,source.width/(float)source.height);for(int y=0;y<size;y++)for(int x=0;x<size;x++){float u=(x+.5f)/size,v=(y+.5f)/size;var c=source.GetPixelBilinear(.5f+(u-.5f)*cropX,.5f+(v-.5f)*cropY);if(dim){float gray=c.r*.2126f+c.g*.7152f+c.b*.0722f;c.r=Mathf.Lerp(c.r,gray,.85f)*.6f;c.g=Mathf.Lerp(c.g,gray,.85f)*.6f;c.b=Mathf.Lerp(c.b,gray,.85f)*.6f;c.r=(c.r-.5f)*.92f+.5f;c.g=(c.g-.5f)*.92f+.5f;c.b=(c.b-.5f)*.92f+.5f;}float dx=(u-.5f)*size,dy=(v-.5f)*size;c.a*=Mathf.Clamp01(size*.5f-Mathf.Sqrt(dx*dx+dy*dy)+.5f);pixels[y*size+x]=c;}result.SetPixels(pixels);result.Apply(false,true);return result;}}}
